corporate_design.toad_component_blueprint:
canvas {
  size: 960px 640px;
  fill: #F8F9FA;
  font-family: "Plus Jakarta Sans, sans-serif";
}

>brandGreen = #79B828;
>ctaAubergine = #6D213F;
>greenTint = #EBF7DC;
>darkSlate = #1F2428;
>bodySlate = #495057;
>bgWhite = #FFFFFF;

rect #floatingHeader {
  at: top center of canvas offset 0px 32px;
  size: 880px 64px;
  fill: >bgWhite;
  radius: 9999px;
}

text #brandLogo {
  at: left center of #floatingHeader offset 32px 0px;
  content: "VELORA";
  font-size: 22px;
  font-weight: 800;
  color: >brandGreen;
}

rect #headerCtaBtn {
  at: right center of #floatingHeader offset -12px 0px;
  size: 190px 44px;
  fill: >ctaAubergine;
  radius: 9999px;
}

text #headerCtaLabel {
  at: center of #headerCtaBtn;
  content: "Kostenlos testen";
  font-size: 14px;
  font-weight: 700;
  color: #FFFFFF;
}

rect #heroCard {
  at: below #floatingHeader offset 32px;
  size: 880px 460px;
  fill: >bgWhite;
  radius: 18px;
}

rect #featurePill {
  at: top left of #heroCard offset 40px 40px;
  size: 190px 28px;
  fill: >greenTint;
  radius: 9999px;
}

text #featurePillText {
  at: center of #featurePill;
  content: "CLOUD ERP FÜR KMU";
  font-size: 11px;
  font-weight: 700;
  color: >brandGreen;
}

text #heroHeadline {
  at: below #featurePill offset 18px;
  size: 560px;
  content: "Einfach, flexibel und nah am Mittelstand.";
  font-size: 38px;
  font-weight: 800;
  color: >darkSlate;
}

text #heroSubtext {
  at: below #heroHeadline offset 16px;
  size: 540px;
  content: "Control inventory, CRM, and finance in a single intuitive cloud platform — built by a team that understands your business.";
  font-size: 16px;
  color: >bodySlate;
}

rect #primaryActionBtn {
  at: below #heroSubtext offset 32px;
  size: 230px 52px;
  fill: >ctaAubergine;
  radius: 9999px;
}

text #primaryActionLabel {
  at: center of #primaryActionBtn;
  content: "Jetzt Demo vereinbaren";
  font-size: 14px;
  font-weight: 700;
  color: #FFFFFF;
}

rect #iconBoxSample {
  at: top right of #heroCard offset -40px 40px;
  size: 56px 56px;
  fill: >greenTint;
  radius: 10px;
}

text #iconSampleGlyph {
  at: center of #iconBoxSample;
  content: "⚙";
  font-size: 28px;
  color: >brandGreen;
}
